%% ============================================================
% EXP008B - POSTPROCESS ALIGNED IQ PAIRS: FIR / MEMORY DIAGNOSTIC
% ============================================================
% Use after EXP008_SyncRootCause_DPDV2_TXDSA5_v1.m.
%
% Goal:
%   Distinguish true bad synchronization from linear memory/group-delay effects.
%
% Input:
%   *_best-per-point.csv generated by EXP008.
%   The CSV must contain AlignedPairFile paths. Each MAT file must contain:
%       x_aligned, y_aligned_raw or y_corrected/y_normalized, sampleRate, txGain
%
% Output:
%   CSV with scalar NMSE and FIR-equalized NMSE for several FIR lengths.
%
% Interpretation:
%   If scalar NMSE is modest (-13 to -15 dB) but FIR NMSE improves strongly
%   (-20 dB or better), the issue is not gross sync failure. It is mainly
%   linear memory / group delay / fractional-delay mismatch in the observation path.
%
% Author: ChatGPT, adapted for DPDV2 workflow.
%% ============================================================

clear; clc;
warning('off','all')

%% =========================
% USER CONFIGURATION
% ==========================
% Paste here the best-per-point CSV generated by EXP008.
% Example:
% bestPerPointCsvFile = "C:\\...\\processed\\EXP008_..._best-per-point.csv";
bestPerPointCsvFile = "";

% If empty, ask user via file picker.
if strlength(bestPerPointCsvFile) == 0
    [f,p] = uigetfile('*.csv','Select EXP008 *_best-per-point.csv');
    if isequal(f,0)
        error('No CSV selected.');
    end
    bestPerPointCsvFile = string(fullfile(p,f));
end

% FIR lengths to test. Odd lengths are recommended.
firLengthList = [1 3 5 9 17 33];

% Number of samples used per point. Use fewer samples to keep LS stable/fast.
maxSamplesToUse = 120000;

% Number of initial samples discarded after alignment to avoid transient edge effects.
discardInitialSamples = 200;

% Normalize columns before LS to improve conditioning.
removeMeanBeforeFit = true;

% Use y_corrected if present. For EXP008 NORMAL_NO_CFO, y_corrected = y_aligned_raw.
yFieldPreference = ["y_corrected", "y_cfo_corrected", "y_aligned_raw", "y_normalized"];

%% =========================
% OUTPUT
% ==========================
[baseDir, baseName, ~] = fileparts(bestPerPointCsvFile);
outCsv = fullfile(baseDir, baseName + "_FIR_memory_diagnostic.csv");
outMat = fullfile(baseDir, baseName + "_FIR_memory_diagnostic.mat");

T = readtable(bestPerPointCsvFile);
if ~ismember('AlignedPairFile', string(T.Properties.VariableNames))
    error('The CSV does not contain AlignedPairFile. Re-run EXP008 with saveBestAlignedPair = true.');
end

rows = {};

for i = 1:height(T)
    txGain = getTableValueSafe(T, i, 'TxGain_dB');
    rxGain = getTableValueSafe(T, i, 'RxGain_dB');
    syncMetricCsv = getTableValueSafe(T, i, 'SyncMetric');
    nmseCsv = getTableValueSafe(T, i, 'NMSE_aligned_dB');
    evmNrCsv = getTableValueSafe(T, i, 'EVM_NR_Aligned_pct');
    upCompCsv = getTableValueSafe(T, i, 'UpconverterCompressionEstimated_dB');

    pairFile = string(T.AlignedPairFile(i));
    if strlength(pairFile) == 0 || ~exist(pairFile, 'file')
        warning('Aligned pair file not found for row %d: %s', i, pairFile);
        rows(end+1,:) = {i, txGain, rxGain, string(pairFile), NaN, NaN, NaN, NaN, NaN, syncMetricCsv, nmseCsv, evmNrCsv, upCompCsv, "missing_pair_file"}; %#ok<SAGROW>
        continue;
    end

    S = load(pairFile);
    if ~isfield(S,'x_aligned')
        warning('x_aligned missing in %s', pairFile);
        rows(end+1,:) = {i, txGain, rxGain, string(pairFile), NaN, NaN, NaN, NaN, NaN, syncMetricCsv, nmseCsv, evmNrCsv, upCompCsv, "missing_x_aligned"}; %#ok<SAGROW>
        continue;
    end

    x = S.x_aligned(:);
    y = [];
    yFieldUsed = "";
    for yf = yFieldPreference
        if isfield(S, yf)
            y = S.(yf)(:);
            yFieldUsed = yf;
            break;
        end
    end
    if isempty(y)
        warning('No usable y field found in %s', pairFile);
        rows(end+1,:) = {i, txGain, rxGain, string(pairFile), NaN, NaN, NaN, NaN, NaN, syncMetricCsv, nmseCsv, evmNrCsv, upCompCsv, "missing_y_field"}; %#ok<SAGROW>
        continue;
    end

    N = min([numel(x), numel(y), maxSamplesToUse]);
    x = x(1:N);
    y = y(1:N);

    if discardInitialSamples > 0 && N > discardInitialSamples + 1000
        x = x(discardInitialSamples+1:end);
        y = y(discardInitialSamples+1:end);
    end

    if removeMeanBeforeFit
        x = x - mean(x,'omitnan');
        y = y - mean(y,'omitnan');
    end

    % Scalar complex gain diagnostic: y ~= g*x.
    gScalar = (x' * y) / (x' * x + eps);
    yScalarHat = gScalar * x;
    scalarNmse_y_dB = 10*log10(sum(abs(y - yScalarHat).^2) / (sum(abs(y).^2)+eps) + eps);

    bestFirLen = NaN;
    bestFirNmse_y_dB = Inf;
    bestFirNmse_x_dB = Inf;
    bestCondition = NaN;
    bestStatus = "";

    for L = firLengthList
        try
            [nmseYdB, nmseXdB, condX] = fitComplexFIRMemoryDiagnostic(x, y, L);
            if nmseYdB < bestFirNmse_y_dB
                bestFirNmse_y_dB = nmseYdB;
                bestFirNmse_x_dB = nmseXdB;
                bestFirLen = L;
                bestCondition = condX;
                bestStatus = "ok";
            end
        catch ME
            bestStatus = "fir_error:" + string(ME.message);
        end
    end

    firImprovement_dB = scalarNmse_y_dB - bestFirNmse_y_dB;

    rows(end+1,:) = {i, txGain, rxGain, string(pairFile), string(yFieldUsed), ...
        scalarNmse_y_dB, bestFirLen, bestFirNmse_y_dB, bestFirNmse_x_dB, ...
        firImprovement_dB, bestCondition, syncMetricCsv, nmseCsv, evmNrCsv, upCompCsv, bestStatus}; %#ok<SAGROW>
end

R = cell2table(rows, 'VariableNames', { ...
    'RowIndex','TxGain_dB','RxGain_dB','AlignedPairFile','YFieldUsed', ...
    'ScalarNMSE_y_dB','BestFIRLength','BestFIR_NMSE_y_dB','BestFIR_NMSE_x_dB', ...
    'FIRImprovement_dB','BestFIRConditionNumber','SyncMetric_CSV','NMSE_aligned_CSV_dB', ...
    'EVM_NR_Aligned_pct','UpconverterCompressionEstimated_dB','Status'});

writetable(R, outCsv);
save(outMat, 'R', 'T', 'firLengthList', 'maxSamplesToUse', 'discardInitialSamples', 'removeMeanBeforeFit');

disp('========== EXP008B FIR / MEMORY DIAGNOSTIC ==========' );
disp(R(:, {'TxGain_dB','SyncMetric_CSV','NMSE_aligned_CSV_dB','ScalarNMSE_y_dB','BestFIRLength','BestFIR_NMSE_y_dB','FIRImprovement_dB','EVM_NR_Aligned_pct','UpconverterCompressionEstimated_dB','Status'}));
fprintf('\nCSV saved: %s\n', outCsv);
fprintf('MAT saved: %s\n', outMat);

warning('on','all')

%% ============================================================
% LOCAL FUNCTIONS
% ============================================================
function val = getTableValueSafe(T, i, name)
    if ismember(name, string(T.Properties.VariableNames))
        val = T.(name)(i);
    else
        val = NaN;
    end
end

function [nmseYdB, nmseXdB, condX] = fitComplexFIRMemoryDiagnostic(x, y, L)
% Fit y[n] ~= sum_k h[k] x[n-k], centered FIR.
% nmseYdB: error normalized to y power.
% nmseXdB: error normalized to scalar-aligned x power after y estimate is normalized back.

    x = x(:);
    y = y(:);
    L = round(L);
    if L < 1
        error('Invalid FIR length.');
    end
    if mod(L,2) == 0
        error('Use odd FIR length.');
    end

    N = min(numel(x), numel(y));
    if N < 10*L
        error('Not enough samples for FIR length %d.', L);
    end

    half = floor(L/2);
    nValid = (1+half):(N-half);
    M = numel(nValid);
    X = complex(zeros(M,L));
    for k = 1:L
        lag = k - (half+1);
        X(:,k) = x(nValid - lag);
    end
    yv = y(nValid);
    xv = x(nValid);

    % Least-squares FIR channel from x to y.
    h = X \ yv;
    yHat = X*h;
    errY = yv - yHat;
    nmseYdB = 10*log10(sum(abs(errY).^2)/(sum(abs(yv).^2)+eps) + eps);

    % Normalize yHat back to x scale and compute equivalent x-domain NMSE.
    gBack = (yHat' * xv) / (yHat' * yHat + eps);
    xHat = gBack * yHat;
    errX = xHat - xv;
    nmseXdB = 10*log10(sum(abs(errX).^2)/(sum(abs(xv).^2)+eps) + eps);

    s = svd(X, 'econ');
    condX = max(s)/(min(s)+eps);
end
